    "type": "git",
    "url": "https://github.com/mlflow/mlflow.git"
  },
  "homepage": "https://mlflow.org/",
  "author": {
    "name": "MLflow",
    "url": "https://mlflow.org/"
  },
  "bugs": {
    "url": "https://github.com/mlflow/mlflow/issues"
  },
  "license": "Apache-2.0",
  "keywords": [
    "mlflow",
    "tracing",
    "observability",
    "opencode",
    "llm",
    "agent",
    "javascript",
    "typescript"
  ],
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
